INSERT INTO ong.research_batches (sha256, as_of, snapshot) VALUES ('e650a12f4a78263034cabefa6226fb140de322f7947d3cd5e4f078aef9821d53', '2026-10-22', '{"meta": {"title": "Mapa consolidado de cooperación para ONG en Cusco", "version": "0.3", "as_of": "2026-10-22", "timezone": "America/Lima", "scope": "Europa, Norteamérica, Asia prioritaria, Oceanía y fuentes complementarias; cobertura parcial", "organization_stage": "por_constituir", "currency_policy": "Monedas originales, sin conversión de tipo de cambio", "batches": ["europa_2026-10-22.json", "america_asia_oceania_2026-10-22.json"]}, "sources": [{"id": "S01", "title": "Chequia: convocatoria completa 2027", "url": "https://mzv.gov.cz/lima/es/comercio_y_economia/convocatoria_2027_para_proyectos_de_1.html", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Cierre, monto, registro y exclusiones explícitos. Publicada 15/09/2026."}, {"id": "S02", "title": "Suiza: proyectos culturales", "url": "https://www.schweiz-peru.eda.admin.ch/es/proyectos-culturales", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Página de 28/09/2026; regla anual de recepción, vínculo suizo y monto."}, {"id": "S03", "title": "Alemania: cooperación para el desarrollo", "url": "https://lima.diplo.de/pe-es/willkommen/07-entwicklungszusammenarbeit", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Coordinación bilateral; GIZ y KfW. No acredita un fondo local abierto."}, {"id": "S04", "title": "IKI Small Grants 2026", "url": "https://www.international-climate-initiative.com/en/find-funding/small-grants/small-grants-2026/", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "Anuncio oficial recuperado por buscador; apertura futura condicionada; reapertura directa falló."}, {"id": "S05", "title": "IKI Medium Grants 2026", "url": "https://www.international-climate-initiative.com/en/find-funding/medium-grants/medium-grants-2026/", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Entidad líder alemana; fechas y prioridades publicadas."}, {"id": "S06", "title": "Fondo Regional de Cooperación Triangular: convocatoria", "url": "https://fondo-cooperacion-triangular.net/", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "29.ª convocatoria; cierre 31/10/2026. Contradice listado APCI anterior."}, {"id": "S07", "title": "Fondo Regional: proceso de postulación", "url": "https://fondo-cooperacion-triangular.net/convocatorias-de-proyecto/", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Entrega por embajadas alemanas, aval rector y compromisos; sin envío directo al Fondo."}, {"id": "S08", "title": "Reino Unido: diálogos ciudadanos 2024", "url": "https://www.gov.uk/government/news/call-for-bids-creating-spaces-for-citizen-dialogues", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Antecedente cerrado. Contiene inconsistencia: notificación a comienzos de octubre pese al cierre de octubre; no extrapolar."}, {"id": "S09", "title": "Reino Unido: derechos LGBT+ en empleo", "url": "https://www.gov.uk/government/news/call-for-bids-peru-promoting-lgbt-rights-in-the-workplace", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "Antecedente de 2024 con ejecución hasta marzo 2025."}, {"id": "S10", "title": "UE: sociedad civil, empleo juvenil 2024", "url": "https://www.eeas.europa.eu/delegations/per%C3%BA/convocatoria-local-del-programa-tem%C3%A1tico-%E2%80%9Cuna-europa-global-para-las-organizaciones-de-la-sociedad_es", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "Referencia 179470; cierre 21/05/2024."}, {"id": "S11", "title": "IILA: Perú Social 2026", "url": "https://iila.org/es/convocatoria-de-subvenciones-para-experiencias-innovadoras-de-respuesta-a-problemas-de-exclusion-social-y-economica-de-personas-en-situacion-de-vulnerabilidad-con-enfasis-en-la-generacion-de-empleo-d/", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Cierre 30/09/2026 17:00 Roma y anexos; ya cerrado."}, {"id": "S12", "title": "UE: anuncio Perú Social", "url": "https://www.eeas.europa.eu/delegations/peru/convocatoria-de-subvenciones-para-experiencias-innovadoras-de-respuesta-problemas-de-exclusion_es", "checked_on": "2026-10-22", "level": "primaria", "access": "contenido_consultado", "note": "Identifica a IILA como gestor y gare@iila.org como canal."}, {"id": "S13", "title": "AECID: convocatorias Perú", "url": "https://peru.aecid.es/convocatorias", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "Incluye formación, que no equivale a subvención."}, {"id": "S14", "title": "AECID: contacto Perú", "url": "https://peru.aecid.es/somos-aecid/contacto", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "Canal local de cooperación oce.peru@aecid.es."}, {"id": "S15", "title": "AECID: memoria FCAS Perú 2022", "url": "https://memoriafcas2022.aecid.es/peru/", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "AMSAT Cusco-Apurímac finalizó en septiembre 2022."}, {"id": "S16", "title": "Cooperación Española: marco Perú 2024–2027", "url": "https://www.cooperacionespanola.es/wp-content/uploads/2025/04/MADS-Espana-Peru-2024-27_compressed-1.pdf", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "Marco plurianual; no es anuncio de convocatoria 2027."}, {"id": "S17", "title": "Suiza: programa Perú", "url": "https://www.schweiz-peru.eda.admin.ch/es/programa-de-cooperacion-ci", "checked_on": "2026-10-22", "level": "primaria", "access": "extracto_buscador", "note": "SECO 2025–2028, gobernanza y economía inclusiva."}, {"id": "S18", "title": "S